function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmt(n){return new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n)}
function episodeRank(s){const m=String(s||'').match(/Ep\.\s*(\d+(?:\.\d+)?)/i);return m?Number(m[1]):-1}
function sortEpisodes(groups){return groups.sort((a,b)=>episodeRank(b[0][0])-episodeRank(a[0][0])||String(a[0][0]).localeCompare(String(b[0][0]),'pt-BR'))}
function itemIcon(name){const id=ICON_IDS[String(name||'').trim()];return id?`<img class="item-icon" src="assets/icons/${id}.png" alt="" loading="lazy" onerror="this.remove()">`:''}
function itemHref(name){const clean=String(name||'').trim().replace(/\s+\[\d+\]$/,'');const id=ICON_IDS[String(name||'').trim()]||ICON_IDS[clean];if(id)return `https://www.divine-pride.net/database/item/${id}`;const query=/Vivatus Fides/i.test(clean)?'Vivatus Fides':/Adulter Fides/i.test(clean)?'Adulter Fides':/Autom[oó]dulo/i.test(clean)?'Module':/Lobo Cinzento/i.test(clean)?'Grey Wolf':clean;return `https://www.divine-pride.net/database/item?query=${encodeURIComponent(query)}&server=LATAM`;}
function itemLink(name,label=null){const n=String(name||'').trim();if(/varia por habilidade|lista a confirmar/i.test(n))return esc(n);return n?`<a class="item-link" href="${itemHref(n)}" title="Abre no Divine Pride (confira se o servidor LATAM está selecionado)" target="_blank" rel="noopener noreferrer">${label??`${itemIcon(n)}${esc(n)}`}</a>`:'—'}
function parseTSV(txt){return txt.replace(/^﻿/,'').split(/\r?\n/).filter(Boolean).map(line=>line.split('\t').map(x=>x.trim()))}
async function loadData(){const entries=Object.entries(DATA_FILES);await Promise.all(entries.map(async([key,path])=>{const response=await fetch(path);if(!response.ok)throw Error(`Não foi possível carregar ${path}`);const body=await response.text();db[key]=(key==='itemIds'||key==='reformaPagina'||key==='guia'||key==='recompensas')?JSON.parse(body):parseTSV(body)}));Object.assign(ICON_IDS,db.itemIds||{});for(const key of ['flechas','toxina','veneno','runas','preparar','manipular','farmacia','culinaria'])for(const r of db[key]||[]){if(r[0]&&r[2])ICON_IDS[r[2]]=r[0];if(r[4]&&r[6])ICON_IDS[r[6]]=r[4]}}
function getRecipes(id){const meta=RECIPE_META[id];if(!meta)return [];let active='',recipes=[];for(const r of (db[meta.key]||[]).slice(id==='flechas'?2:1)){if(r[meta.product]){active=r[meta.product];recipes.push({name:active,raw:r,materials:[]})}if(active&&r[meta.material]){const recipe=recipes[recipes.length-1],name=r[meta.material],qty=r[meta.quantity]||'1';let material=recipe.materials.find(m=>m.name===name);if(!material){material={name,quantities:[]};recipe.materials.push(material)}material.quantities.push(qty)}}return recipes}
