const TABLES={equipamentos:{key:'equips',title:'Equipamentos de episódio',desc:'Peças disponíveis, NPCs, materiais de troca e observações.',cols:[[0,'Episódio'],[1,'Categoria'],[3,'Equipamento'],[4,'NPC'],[5,'/navi'],[7,'Material'],[8,'Qtd.'],[10,'Material 2'],[11,'Qtd. 2'],[12,'Observação']],filters:[0,1]},encantamentos:{key:'encantos',title:'Encantamentos disponíveis',desc:'Efeitos listados por episódio, equipamento-alvo e slot.',cols:[[0,'Episódio'],[1,'Equipamento-alvo'],[2,'Slot'],[3,'Tipo de efeito'],[5,'Encantamento'],[6,'Efeito'],[8,'Item consumido'],[9,'Chance (%)'],[10,'Observação']],filters:[0,1,2]},custos:{key:'custo',title:'Custos de encantamento',desc:'Materiais, quantidades, NPCs e observações para preparar cada encantamento.',cols:[[0,'Episódio'],[1,'Equipamento-alvo'],[2,'Slot'],[3,'Tipo de efeito'],[5,'Material'],[6,'Qtd.'],[7,'NPC / origem'],[8,'/navi'],[9,'Observação']],filters:[0,1,2]}};
