/* ===== v1.3: encantamento total, Grau do Ep. 19 e reciclagem ===== */
const EP19_IDS={'Minério Mágico da Flor de Neve':1000811,'Globo de Flor Invernal':1000812,'Globo de Flor Invernal Brilhante':1000813,'Globo de Flor Invernal Reluzente':1000814,'Pedra da Fonte Mágica Corrompida':1001029,'Pedra da Fonte Mágica Purificada':1001030,'Cristal Mágico Corrompido':1001031,'Cristal Mágico Purificado':1001032,'Magia Corrompida':1001033,'Extrato de Pedra Mágica da Flor de Neve':1001034,'Extrato de Pedra Mágica Brilhante da Flor de Neve':1001035,'Extrato de Pedra Mágica Radiante da Flor de Neve':1001036,'Extrato Glacial':1001037};
Object.entries(EP19_IDS).forEach(([k,v])=>{ICON_IDS[k]??=v});
const GRAU19={steps:['Aplicar Nv. 1','Nv. 1 → 2','Nv. 2 → 3','Nv. 3 → 4','Nv. 4 → 5'],mats:[['Extrato de Pedra Mágica Radiante da Flor de Neve',[60,30,40,50,65]],['Extrato de Pedra Mágica Brilhante da Flor de Neve',[40,20,30,40,50]],['Extrato de Pedra Mágica da Flor de Neve',[30,15,20,30,40]],['Extrato Glacial',[50,25,35,45,70]],['Cristal Mágico Corrompido',[0,5,7,10,15]],['Cristal Mágico Purificado',[0,5,7,10,15]],['Magia Corrompida',[0,0,1,2,3]]]};
const RECYCLE19=[['Minério e Pedras da Fonte Mágica',[['Minério Mágico da Flor de Neve',1,4],['Pedra da Fonte Mágica Corrompida',1,4],['Pedra da Fonte Mágica Purificada',1,3]]],['Globos de Flor Invernal',[['Globo de Flor Invernal',1,3],['Globo de Flor Invernal Brilhante',1,3],['Globo de Flor Invernal Reluzente',1,2]]],['Extratos de Pedra Mágica',[['Extrato de Pedra Mágica da Flor de Neve',1,1],['Extrato de Pedra Mágica Brilhante da Flor de Neve',1,1],['Extrato de Pedra Mágica Radiante da Flor de Neve',1,1],['Extrato Glacial',1,1]]],['Cristais e Magia Corrompida',[['Cristal Mágico Corrompido',1,2],['Cristal Mágico Purificado',1,2],['Magia Corrompida',1,1]]]];
const EXTRA_CALCS=[{id:'encanto',kind:'Materiais totais',title:'Custo total de encantamento',desc:'Soma os materiais dos efeitos escolhidos em cada slot. Os aleatórios do Ep. 19 ficam de fora; nos demais episódios o custo de cada sorteio é somado.'},];
const EXTRA_PANELS={encanto:enchantPanel},EXTRA_UPDATE={encanto:updateEnchantCalc};
const numQty=s=>{s=String(s??'').trim();if(/^\d{1,3}(\.\d{3})+$/.test(s))return Number(s.replace(/\./g,''));const n=Number(s.replace(',','.'));return s&&Number.isFinite(n)?n:NaN};
const totalList=(map,extras=[])=>[...map].map(([n,q])=>`<div class="ingredient"><span class="item-label">${itemLink(n)}</span><b>${fmt(q)}</b></div>`).join('')+extras.map(x=>`<div class="ingredient"><span>${esc(x)}</span><b>sem total</b></div>`).join('');
function enchIsRandom(g){return /aleat/i.test(g.map(x=>x.join(' ')).join(' '))||g.every(x=>/^P[eé]tala de Flor Invernal$/i.test(x[5]||''))}
const slotPos=s=>{const a=[...String(s||'').matchAll(/\{(\d)\}/g)].map(m=>+m[1]);if(a.length)return a;const m=String(s||'').match(/slot\s*(\d)/i);return m?[+m[1]]:[]};
function enchIndex(){const idx=new Map();groupBy((db.custo||[]).slice(1).filter(r=>r[0]&&r[1]&&r[5]),r=>[r[0],r[1],r[2],r[3]].join('\x00')).forEach(g=>{const r=g[0];if(/reset/i.test(r[3]||'')||(/\b19\b/.test(r[0])&&enchIsRandom(g)))return;if(!idx.has(r[0]))idx.set(r[0],new Map());const E=idx.get(r[0]);if(!E.has(r[1]))E.set(r[1],[]);E.get(r[1]).push({slot:r[2]||'',pos:slotPos(r[2]),effect:r[3]||'—',mats:[...new Map(g.map(x=>[[x[5],x[6]].join('\x00'),x])).values()].map(x=>({name:x[5],qty:x[6]}))})});return idx}
function enchantPanel(){const eps=[...enchIndex().keys()].sort((a,b)=>episodeRank(b)-episodeRank(a)),lv=n=>n?`Nv. ${n}`:'Sem grau (aplicar Nv. 1)';return `<section class="calculator" data-active-calc="encanto"><div class="card calc-form"><h3>Custo total de encantamento</h3><p>Escolha o episódio, o equipamento e o efeito de cada encantamento (posições 1, 2, 3…). Aleatórios do Ep. 19 ficam de fora; nos demais episódios o custo de cada sorteio é somado. No Ep. 19 dá para incluir os materiais do upgrade de grau da Vis Invernal.</p><div class="fields"><div class="field"><label for="ecEp">Episódio</label><select id="ecEp">${eps.map(e=>`<option>${esc(e)}</option>`).join('')}</select></div><div class="field"><label for="ecTarget">Equipamento-alvo</label><select id="ecTarget"></select></div></div><div class="fields" data-grau hidden style="margin-top:11px"><div class="field"><label for="ecGrauDe">Grau da Vis Invernal — de</label><select id="ecGrauDe">${[0,1,2,3,4].map(n=>`<option value="${n}">${lv(n)}</option>`).join('')}</select></div><div class="field"><label for="ecGrauAte">até</label><select id="ecGrauAte">${[1,2,3,4,5].map(n=>`<option value="${n}"${n===5?' selected':''}>Nv. ${n}</option>`).join('')}</select></div><p class="table-search-note">Materiais do upgrade de grau (slot 2 das Armas Vis Invernais). Fonte: <a class="table-link" href="https://browiki.org/wiki/Equipamentos_Invernais" target="_blank" rel="noopener noreferrer">bROWiki · Equipamentos Invernais ↗</a></p></div><div class="fields" id="ecSlots" style="margin-top:11px"></div><p class="table-search-note" id="ecHint" style="margin-top:10px"></p></div><div class="card calc-result"><div class="eyebrow">CUSTO TOTAL</div><h3 id="ecTitle">—</h3><p id="ecNote"></p><div class="ingredient-list" id="ecTotals"></div></div></section>`}
function updateEnchantCalc(sec){const idx=enchIndex(),ep=sec.querySelector('#ecEp'),tg=sec.querySelector('#ecTarget'),box=sec.querySelector('#ecSlots'),hint=sec.querySelector('#ecHint'),is19=/Ep\.\s*19\b/.test(ep.value);
sec.querySelectorAll('[data-grau]').forEach(el=>el.hidden=!is19);
if(tg.dataset.ep!==ep.value){tg.dataset.ep=ep.value;tg.innerHTML=[...(idx.get(ep.value)?.keys()||[])].map(t=>`<option>${esc(t)}</option>`).join('')}
const E=idx.get(ep.value)?.get(tg.value)||[],fixed=E.filter(e=>e.pos.length),any=E.filter(e=>!e.pos.length),key=ep.value+'\x00'+tg.value;
if(box.dataset.key!==key){box.dataset.key=key;const positions=[...new Set(fixed.flatMap(e=>e.pos))].sort((a,b)=>a-b),opt=e=>`<option value="${E.indexOf(e)}">${esc(e.effect)}</option>`;
let h=positions.map(p=>{const list=fixed.filter(e=>e.pos.includes(p)).sort((x,y)=>x.pos.length-y.pos.length);return `<div class="field"><label for="ecPos${p}">Encantamento ${p}</label><select id="ecPos${p}" data-pos="${p}">${list.map(opt).join('')}<option value="-1">— nenhum —</option></select></div>`}).join('');
if(any.length){const n=Number((any[0].slot.match(/até\s*(\d+)/i)||[])[1])||1;h+=`<div class="field"><label for="ecAny">Efeito do encantamento</label><select id="ecAny" data-any>${any.map(opt).join('')}<option value="-1">— nenhum —</option></select></div><div class="field"><label for="ecAnyN">Quantidade de encantos</label><select id="ecAnyN">${Array.from({length:n},(_,k)=>`<option>${k+1}</option>`).join('')}</select></div>`}
box.innerHTML=h||'<p class="muted">Sem dados para este equipamento.</p>';
const multi=[...new Set(fixed.filter(e=>e.pos.length>1).map(e=>e.effect))].map(f=>{const ps=fixed.find(e=>e.effect===f&&e.pos.length>1).pos;return `“${f}” pode ser usado nos encantamentos ${ps.length>1?`${ps.slice(0,-1).join(', ')} ou ${ps[ps.length-1]}`:ps[0]}`});
hint.textContent=multi.length?multi.join('. ')+'.':''}
const totals=new Map(),extras=[],picked=[];
const add=(e,n,label)=>{picked.push(`${label}: ${e.effect}${n>1?` ×${n}`:''}`);e.mats.forEach(m=>{const q=numQty(m.qty);if(m.name&&!Number.isNaN(q)&&!/variados|a confirmar|varia por habilidade/i.test(m.name))totals.set(m.name,(totals.get(m.name)||0)+q*n);else if(m.name||m.qty)extras.push(`${m.qty||''} ${m.name||''}`.trim()+` (${label})`)})};
box.querySelectorAll('[data-pos]').forEach(s=>{const e=E[Number(s.value)];if(e)add(e,1,`Encantamento ${s.dataset.pos}`)});
const sa=box.querySelector('[data-any]');if(sa){const e=E[Number(sa.value)];if(e)add(e,Number(box.querySelector('#ecAnyN').value)||1,'Encantamentos')}
let grauNota='';
if(is19){const gf=Number(sec.querySelector('#ecGrauDe').value),gt=Number(sec.querySelector('#ecGrauAte').value);if(gt>gf){GRAU19.mats.forEach(([nm,c])=>{const q=c.slice(gf,gt).reduce((a,b)=>a+b,0);if(q>0)totals.set(nm,(totals.get(nm)||0)+q)});grauNota=` · Inclui o upgrade de grau da Vis Invernal (${gf?`Nv. ${gf}`:'sem grau'} → Nv. ${gt}).`}}
$('#ecTitle').textContent=picked.length||grauNota?'Custo de 1 equipamento':'Escolha ao menos um efeito';
$('#ecNote').textContent=(picked.join(' · ')||'Nenhum efeito escolhido.')+grauNota+(picked.some(p=>p.includes('*'))?' · * Valores do Hazy Forest (kRO); podem não corresponder ao valor real na bROWiki.':'');
$('#ecTotals').innerHTML=totalList(totals,extras)}
function recycleView(){const body=RECYCLE19.map(([group,items])=>items.map((it,i)=>`<tr>${i===0?`<td rowspan="${items.length}"><b>3 × Arma Vis Invernal [1]</b><span class="table-meta">escolhidas por você</span><span class="table-meta">${esc(group)}</span></td>`:''}<td><span class="item-label">${itemLink(it[0])}</span></td><td>${it[1]===it[2]?it[1]:`${it[1]} ~ ${it[2]}`}</td></tr>`).join('')).join('');
return `<div class="page-head"><div><div class="eyebrow">ISSGARD · EPISÓDIO 19</div><h1 class="page-title">Reciclagem de itens</h1><p class="page-subtitle">O que o Incinerador devolve ao reciclar armas Vis Invernais.</p></div><span class="count-pill">${RECYCLE19.length} GRUPOS</span></div><div class="panel-note"><b>Como funciona:</b> fale com o Incinerador no quartel (/navi icas_in 192/58). Cada reciclagem consome 3 Armas Vis Invernais e entrega materiais de encantamento em quantidades variáveis. <a href="https://browiki.org/wiki/Equipamentos_Invernais" target="_blank" rel="noopener noreferrer">Fonte: bROWiki · Equipamentos Invernais ↗</a></div><div class="section-heading"><div><h2>Resultados possíveis</h2><p>Faixas “mín ~ máx” indicam quantidade sorteada. A página de origem lista quatro grupos de resultado; confirme lá se são opções do menu ou resultados simultâneos.</p></div></div>${tableFrame(['Entrada','Resultado','Quantidade por reciclagem'],body,'grouped-table align-top')}<div class="section-heading"><div><h2>Estimativa por quantidade</h2><p>Quantas reciclagens você consegue fazer e quanto pode receber de um grupo.</p></div></div><div class="calculator"><div class="card calc-form"><div class="fields"><div class="field"><label>Armas Vis Invernais</label><div class="rc-stepper"><button type="button" class="button" data-rc="sub" aria-label="Remover 3">− 3</button><b id="rcQty">3</b><button type="button" class="button" data-rc="add" aria-label="Adicionar 3">+ 3</button></div></div><div class="field"><label for="rcGroup">Grupo de resultado</label><select id="rcGroup">${RECYCLE19.map((g,i)=>`<option value="${i}">${esc(g[0])}</option>`).join('')}</select></div></div></div><div class="card calc-result"><div class="eyebrow">ESTIMATIVA</div><h3 id="rcTitle">—</h3><div class="ingredient-list" id="rcTotals"></div></div></div>`}
function bindRecycle(){let n=3;const g=()=>RECYCLE19[+$('#rcGroup').value],run=()=>{const cycles=n/3;$('#rcQty').textContent=fmt(n);$('#rcTitle').textContent=`${fmt(cycles)} reciclage${cycles===1?'m':'ns'}`;$('#rcTotals').innerHTML=g()[1].map(it=>`<div class="ingredient"><span class="item-label">${itemLink(it[0])}</span><b>${fmt(it[1]*cycles)}${it[1]===it[2]?'':` ~ ${fmt(it[2]*cycles)}`}</b></div>`).join('')};$$('[data-rc]').forEach(b=>b.onclick=()=>{n=Math.max(3,n+(b.dataset.rc==='add'?3:-3));run()});$('#rcGroup').onchange=run;run()}
/* ===== v1.4: links das atividades e Grau & Refinamento (páginas completas da bROWiki) ===== */
const BW='https://browiki.org/wiki/';
const ACTIVITY_LINKS={'Aventuras em Issgard':BW+'Aventuras_em_Issgard','Operação Destruição':BW+'Opera%C3%A7%C3%A3o_Destrui%C3%A7%C3%A3o','Batalha de Simulação':BW+'Issgard','Patrulha da Águia':BW+'Issgard','Aventuras na Aldeia':BW+'Aventuras_na_Aldeia','Purificação do Santuário':BW+'Purifica%C3%A7%C3%A3o_do_Santu%C3%A1rio','Mansão da Desilusão':BW+'Mans%C3%A3o_da_Desilus%C3%A3o','Aventuras na Mansão':BW+'Aventuras_na_Mans%C3%A3o','Duelo com Sweety':BW+'Duelo_com_Sweety','Fazenda de Pitayas':BW+'Fazenda_de_Pitayas','Jardim Secreto':BW+'Jardim_Secreto','Ortus Aqua':BW+'Ortus_Aqua','Aventuras no Distrito':BW+'Aventuras_no_Distrito','Missão OS':BW+'Miss%C3%A3o_OS','Memorial COR':BW+'Memorial_COR'};
function activityLink(name){const key=String(name||'').split(' – ')[0].replace(/\s*\(.*\)\s*$/,'').trim(),u=ACTIVITY_LINKS[key];return u?`<a class="table-link" href="${u}" target="_blank" rel="noopener noreferrer" title="Abrir a página na bROWiki">${esc(name)}</a>`:esc(name)}
let upMode='normal',upTable='comuns';
const tbl=(thead,body)=>`<div class="table-wrap"><table class="data-table"><thead>${thead}</thead><tbody>${body}</tbody></table></div>`;
const ths=a=>`<tr>${a.map(x=>`<th>${x}</th>`).join('')}</tr>`;
const trs=rows=>rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('');
const ul=a=>`<ul>${a.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const secH=(h,p='')=>`<div class="section-heading"><div><h2>${h}</h2>${p?`<p>${p}</p>`:''}</div></div>`;
const cst=(z,list=[])=>[z,...list.map(([q,n])=>`${q} ${itemLink(n)}`)].filter(Boolean).join(' + ');
const rb=(a,b,v)=>{const r=[];for(let n=a;n<=b;n++)r.push([`+${n}`,...v.split(',').map(x=>x==='-'?'-':x+'%')]);return r};
