const refChanceTable=k=>tbl(`<tr><th rowspan="2">Refino</th><th colspan="5">Arma</th><th colspan="3">Armadura</th></tr><tr><th>Nível 1</th><th>Nível 2</th><th>Nível 3</th><th>Nível 4</th><th>Nível 5</th><th>Nível 1</th><th>Nível 2</th><th>Sombrio</th></tr>`,trs(REF_CH[k]));
