const mine=(rows)=>tbl(ths(['Minério','Nv.','Refina entre','Penalidade da falha','Obtenção via NPC']),trs(rows.map(([n,nv,f,p,c])=>[`<span class="item-label">${itemLink(n)}</span>`,nv,f,p,c])));
function refinoPage(){
return `<div class="panel-note">Refinar significa adicionar mais poder em armas e equipamentos. Itens refinados mostram quantas vezes foram refinados: <code>Espada</code> (sem refino) e <code>+2 Espada</code> (refinado 2 vezes). <a class="table-link" href="${BW}Refinamento" target="_blank" rel="noopener noreferrer">Fonte: bROWiki — Refinamento ↗</a></div>
${secH('Como refinar')}<div class="card" style="padding:16px 20px"><ol><li>Vá para uma Refinaria e fale com o NPC.</li><li>A interface de refino será aberta: arraste o item até a janela e selecione os materiais.</li></ol><b>Preste atenção!</b>${ul(['Existem chances de falha e de perda total do item.','Existe um limite de segurança em que o item pode ser refinado com 100% de sucesso: armas nível 1: +7; armas nível 2: +6; armas nível 3: +5; armas nível 4 e armaduras nível 1: +4; armas nível 5 e armaduras nível 2: +3.','Itens indicados como “Indestrutíveis em Batalha” ainda serão destruídos em refinamentos.','<b>Equipamentos Sombrios:</b> o limite máximo de refino é +10 (não vão até o +20 como os equipamentos comuns); as Manoplas Sombrias têm os mesmos requisitos das armas nível 4; o restante tem nível 1; os acessórios sombrios (Brinco e Colar) podem ser refinados; a Bênção do Ferreiro e os Pergaminhos de Refino não funcionam.'])}</div>
${secH('Bônus por refino','Cada refino dá um bônus acumulativo; ao passar do limite de segurança (Over), o bônus aumenta bastante. Refinado a partir do +15, o item ganha o bônus adicional, que aumenta ATQ e ATQM a cada refino acima do +16. Armas de ataque à distância não recebem bônus de ATQM nem o bônus de Over das outras armas. Equipamentos Sombrios não recebem estes bônus.')}
${tbl(ths(['Arma','ATQ/ATQM por refino','Bônus de Over','Bônus adicional','Bônus adic. por refino','P.ATQ/S.ATQM por refino']),trs([['Nv.1','2','1 ~ 3','16','1','-'],['Nv.2','3','1 ~ 5','32','2','-'],['Nv.3','5','1 ~ 8','32','2','-'],['Nv.4','7','1 ~ 14','48','3','-'],['Nv.5 sem Grau','8','-','-','-','2'],['Nv.5 e Grau D','8,8','-','-','-','2'],['Nv.5 e Grau C','10,4','-','-','-','2'],['Nv.5 e Grau B','12','-','-','-','2'],['Nv.5 e Grau A','16','-','-','-','2']]))}
<div style="height:12px"></div>${tbl(`<tr><th rowspan="2">Armadura</th><th colspan="4">DEF/DEFM por refino</th><th rowspan="2">TEN/TENM por refino</th></tr><tr><th>+1 ~ +4</th><th>+5 ~ +8</th><th>+9 ~ +12</th><th>+13 ~ +20</th></tr>`,`<tr><td>Nv.1</td><td>1</td><td>2</td><td>3</td><td>4 ~ 5</td><td>-</td></tr><tr><td>Nv.2</td><td colspan="4">20% da DEF dada pelo refino da armadura</td><td>2</td></tr>`)}
${secH('Minérios','Refinar custa dinheiro e exige o minério correto para o nível do item. Os minérios são obtidos nos NPCs das refinarias, por zeny ou trocando por itens.')}
<h3 class="table-group-title">Minérios comuns para armas</h3>${mine([['Fracon','1','0 ao +9','Perde a arma','200z'],['Emveretarcon','2','0 ao +9','Perde a arma','1.000z'],['Oridecon','3 ~ 4','0 ao +9','Perde a arma',cst('',[[5,'Minério de Oridecon']])],['Bradium','1 ~ 4','+10 ao +19','Perde 3 refinos ou 20% de perda do item',cst('50.000z',[[3,'Oridecon']])],['Eteridecon','5','0 ao +9','Perde 3 refinos',cst('10.000z',[[1,'Oridecon'],[1,'Pó de Éter']])],['Bradium de Éter','5','+10 ao +19','Perde a arma',cst('30.000z',[[1,'Bradium'],[3,'Pó de Éter']])]])}
<h3 class="table-group-title" style="margin-top:16px">Minérios especiais para armas</h3>${mine([['Oridecon Enriquecido','3 ~ 4','0 ao +9','Perde a arma','JoyCoins'],['Oridecon Perfeito','3 ~ 4','+7 ao +9','Perde 1 refino','JoyCoins'],['Bradium Perfeito','1 ~ 4','+10 ao +19','Perde 1 refino','JoyCoins'],['Eteridecon Enriquecido','5','0 ao +9','Perde 1 refino',cst('20.000z',[[1,'Oridecon Enriquecido'],[2,'Pó de Éter']])],['Eteridecon Perfeito','5','+10 ao +14','Perde a arma',cst('50.000z',[[1,'Oridecon Perfeito'],[3,'Pó de Éter']])],['Bradium de Éter Perfeito','5','+15 ao +19','Perde a arma',cst('50.000z',[[1,'Bradium Perfeito'],[3,'Pó de Éter']])]])}
<h3 class="table-group-title" style="margin-top:16px">Minérios comuns para armaduras</h3>${mine([['Elunium','Nv.1','0 ao +9','Perde a armadura',cst('',[[5,'Minério de Elunium']])],['Carnium','Nv.1','+10 ao +19','Perde 3 refinos ou 20% de perda do item',cst('50.000z',[[3,'Elunium']])],['Eterium','Nv.2','0 ao +9','Perde 3 refinos',cst('10.000z',[[1,'Elunium'],[1,'Pó de Éter']])],['Carnium de Éter','Nv.2','+10 ao +19','Perde a armadura',cst('50.000z',[[1,'Carnium'],[3,'Pó de Éter']])]])}
<h3 class="table-group-title" style="margin-top:16px">Minérios especiais para armaduras</h3>${mine([['Elunium Enriquecido','Nv.1','0 ao +9','Perde a armadura','JoyCoins'],['Elunium Perfeito','Nv.1','+7 ao +9','Perde 1 refino','JoyCoins'],['Carnium Perfeito','Nv.1','+10 ao +19','Perde 1 refino','JoyCoins'],['Eterium Enriquecido','Nv.2','0 ao +9','Perde 1 refino',cst('20.000z',[[1,'Elunium Enriquecido'],[2,'Pó de Éter']])],['Eterium Perfeito','Nv.2','+10 ao +14','Perde a armadura',cst('50.000z',[[1,'Elunium Perfeito'],[3,'Pó de Éter']])],['Carnium de Éter Perfeito','Nv.2','+15 ao +19','Perde a armadura',cst('50.000z',[[1,'Carnium Perfeito'],[3,'Pó de Éter']])]])}
${secH('Outros métodos','Na maioria dos casos, são itens especiais.')}
${tbl(ths(['Item','Efeito']),trs([[`<span class="item-label">${itemLink('Bênção do Ferreiro')}</span>`,'Armas e equipamentos não são perdidos nem têm o refino rebaixado em caso de falha.<br>Só pode ser usada junto com outro minério e não funciona com Equipamentos Sombrios.<br>Funciona somente nos refinos +7 ao +13: +7 → +8: 1 un.; +8 → +9: 2 un.; +9 → +10: 4 un.; +10 → +11: 7 un.; +11 → +12: 11 un.; +12 → +13: 16 un.; +13 → +14: 22 un.; +6 e anteriores, e +14 em diante: não funciona.'],[`<span class="item-label">${itemLink('Pergaminho de Refino')}</span>`,'Leva a arma ou o equipamento direto para o refino indicado no pergaminho, sem acumular com refinos já existentes.<br>Não pode ser negociado (vai em envelope no shopping) e não funciona em armas nível 5 nem em equipamentos nível 2.<br>Deve ser levado ao Mestre do Refino (prontera 184/177).'],[`<span class="item-label">${itemLink('Cubos de Refino')}</span>`,'Levam a arma ou o equipamento direto para o refino indicado pelo cubo, sem acumular com refinos já existentes. Funcionam pelo sistema de Combinação.'],[`<span class="item-label">${itemLink('Martelos de Refino')}</span>`,'Funcionam em Equipamentos Sombrios e levam direto ao refino indicado ou a um aleatório, sem acumular com refinos já existentes. Funcionam pelo sistema de Combinação.'],['Manufatura',`Os minérios de manufatura são refinados em qualquer NPC das refinarias: ${cst('',[[20,'Minério de Zelunium']])} → ${itemLink('Zelunium')}; ${cst('',[[20,'Minério de Sombridecon']])} → ${itemLink('Sombridecon')}. Refinador de Prontera (prt_in 62/57).`]]))}`}
function grauPage(){
return `<div class="panel-note">Grau é um sistema de aprimoramento que concede bônus especiais e altera a estética dos equipamentos. Só armaduras nível 2 e armas nível 5 são afetadas. <a class="table-link" href="${BW}Grau" target="_blank" rel="noopener noreferrer">Fonte: bROWiki — Grau ↗</a></div>
${secH('Bônus por grau','Cada Grau adiciona um bônus percentual a cada refino de uma arma nível 5. (O texto da bROWiki diz “nível 2”, mas os valores são os das armas nível 5 da página Refinamento.) A letra do Grau aparece na frente do nome do item, como em [B] Adaga.')}
${tbl(ths(['Arma','ATQ & ATQM por refino','Bônus','Prefixo']),trs([['Sem Grau','+8,00','0% de aumento','—'],['Grau D','+8,80','10% de aumento','[D]'],['Grau C','+10,4','30% de aumento','[C]'],['Grau B','+12,0','50% de aumento','[B]'],['Grau A','+16,0','100% de aumento','[A]']]))}
${secH('Como funciona')}<div class="card" style="padding:16px 20px"><ol><li>Vá para uma refinaria e fale com o NPC com indicação de Grau.</li><li>A interface de Grau será aberta: arraste o item até a janela e selecione os materiais.</li></ol><b>Preste atenção!</b>${ul(['Para subir de grau, o item precisa de um refino mínimo. Quando o Grau sobe, <b>o refino volta para +0</b>.','<b>Processos:</b> em caso de sucesso, encantamentos, cartas e bônus aleatórios são preservados; em caso de falha em processo seguro, também são preservados; em caso de falha fora do processo seguro, o equipamento é perdido.','<b>Materiais:</b> no processo seguro, use 5 minérios em vez de 1; ele garante que o item não seja perdido em caso de falha.','<b>Bênção de Éter:</b> é opcional; cada adição aumenta as chances de sucesso, até 10% no máximo; o número de Bênçãos necessárias para subir 1% varia com o grau.'])}</div>
${secH('Informações','Atualmente, para subir de grau, o item deve estar no +11 no mínimo.')}
${tbl(ths(['Etapa','Refino mínimo','Materiais','Zeny','Penalidade da falha','Chance de sucesso (fora do evento)','Bênção de Éter']),trs([['Sem Grau → Grau D','+11',cst('',[[1,'Aquamarina de Éter']]),'100.000z','Perde tudo','70%','+1% a cada 1 Bênção'],['','',cst('',[[5,'Aquamarina de Éter']]),'500.000z','Seguro','—','—'],['Grau D → Grau C','+11',cst('',[[1,'Topázio de Éter']]),'125.000z','Perde tudo','60%','+1% a cada 3 Bênçãos'],['','',cst('',[[5,'Topázio de Éter']]),'625.000z','Seguro','—','—'],['Grau C → Grau B','+11',cst('',[[1,'Ametista de Éter']]),'200.000z','Perde tudo','50%','+1% a cada 5 Bênçãos'],['','',cst('',[[5,'Ametista de Éter']]),'1.000.000z','Seguro','—','—'],['Grau B → Grau A','+11',cst('',[[2,'Âmbar de Éter']]),'500.000z','Perde tudo','40%','+1% a cada 7 Bênçãos'],['','',cst('',[[10,'Âmbar de Éter']]),'2.500.000z','Seguro','—','—']]))}
${secH('Materiais','Os materiais podem ser obtidos com os NPCs de Grau. Topázio e Âmbar podem ser comprados com a Joalheira (morocc 166/54).')}
${tbl(ths(['Item','Zeny','Materiais']),trs([[`<span class="item-label">${itemLink('Pedra de Éter')}</span>`,'100.000z',cst('',[[5,'Pó de Éter']])],[`<span class="item-label">${itemLink('Bênção do Éter')}</span>`,'100.000z',cst('',[[5,'Pó de Éter'],[1,'Bênção do Ferreiro']])],[`<span class="item-label">${itemLink('Aquamarina de Éter')}</span>`,'100.000z',cst('',[[3,'Pedra de Éter'],[1,'Aquamarina']])],[`<span class="item-label">${itemLink('Topázio de Éter')}</span>`,'200.000z',cst('',[[6,'Pedra de Éter'],[1,'Topázio']])],[`<span class="item-label">${itemLink('Ametista de Éter')}</span>`,'300.000z',cst('',[[10,'Pedra de Éter'],[1,'Ametista']])],[`<span class="item-label">${itemLink('Âmbar de Éter')}</span>`,'500.000z',cst('',[[15,'Pedra de Éter'],[1,'Âmbar']])]]))}`}
function upChance(){const ev=upMode==='evento',suf=ev?' — durante o evento':'';
if(upTable==='grau')return `<h3 class="table-group-title">Grau${suf}: armas e armaduras</h3><p class="table-search-note">O evento de grau aumenta as chances de sucesso ao subir o Grau de um item. É sazonal e fica ativo junto com o Evento de Refino. A bROWiki traz os mesmos valores para armas e armaduras.</p>${grauChanceTable(ev?'evento':'normal')}`;
const esp=upTable==='especiais';
return `<h3 class="table-group-title">Refinamento — minérios ${esp?'especiais':'comuns'}${suf}</h3><p class="table-search-note">O evento de refino aumenta as chances de sucesso nos NPCs de forja e é sazonal.${esp?' Os minérios especiais estão listados mais abaixo, em Refinamento.':''}</p>${refChanceTable((esp?'especiais':'comuns')+(ev?'Ev':''))}`}
function upgradesView(){const sw=(attr,cur,list)=>list.map(([v,l])=>`<button class="subtab ${cur===v?'active':''}" data-${attr}="${v}" type="button">${l}</button>`).join('');
return `<div class="page-head"><div><div class="eyebrow">SISTEMAS DE MELHORIA</div><h1 class="page-title">Grau & Refinamento</h1><p class="page-subtitle">Chances de sucesso (normais e do evento) e, abaixo, o conteúdo das páginas Refinamento e Grau da bROWiki.</p></div><span class="count-pill">CHANCES + DETALHES</span></div>
<div class="up-controls"><div class="subtabs" role="group" aria-label="Tabela"><span class="muted" style="align-self:center;font-size:13px">Tabela:</span>${sw('up-table',upTable,[['comuns','Refino — minérios comuns'],['especiais','Refino — minérios especiais'],['grau','Grau']])}</div>
<div class="subtabs" role="group" aria-label="Versão das chances de sucesso"><span class="muted" style="align-self:center;font-size:13px">Chances de sucesso:</span>${sw('up-mode',upMode,[['normal','Normal'],['evento','Durante o evento']])}</div></div>
<div id="upChance">${upChance()}</div>
${secH('Detalhes','Explicações, bônus, minérios e materiais das páginas Refinamento e Grau da bROWiki.')}${fold('Refinamento',refinoPage(),{open:true,cls:'fold-top'})}${fold('Grau',grauPage(),{open:true,cls:'fold-top'})}`}
function bindUpgrades(){const sync=()=>{$('#upChance').innerHTML=upChance();$$('[data-up-table]').forEach(b=>b.classList.toggle('active',b.dataset.upTable===upTable));$$('[data-up-mode]').forEach(b=>b.classList.toggle('active',b.dataset.upMode===upMode))};$$('[data-up-table]').forEach(b=>b.onclick=()=>{upTable=b.dataset.upTable;sync()});$$('[data-up-mode]').forEach(b=>b.onclick=()=>{upMode=b.dataset.upMode;sync()})}
/* ===== v1.6: seções recolhíveis e página de Reforma (bROWiki) ===== */
const fold=(title,body,o={})=>`<details class="fold ${o.cls||''}"${o.open?' open':''}><summary>${title}${o.count?`<span class="fold-count">${o.count}</span>`:''}</summary><div class="fold-body">${body}</div></details>`;
const refNota=s=>esc(s).replace(/\{\{(.+?)\}\}/g,(_,n)=>itemLink(n));
const refItem=n=>`<span class="item-label">${itemLink(n)}</span>`;
const refArrow='<span class="reform-arrow">→</span>';
const refMats=l=>`<div class="material-lines">${l.map(([q,n])=>`<div class="material-line"><b class="material-qty">${fmt(q)} ×</b>${itemLink(n)}</div>`).join('')}</div>`;
const refReq=inf=>inf.notas.length?`<p class="table-search-note" style="font-size:14px">${inf.notas.map(refNota).join(' · ')}</p>`:'';
const refMethods=inf=>inf.metodos.map(m=>[`<b>${esc(m.nome)}</b>`,esc(m.nota||'—'),refMats(m.mats)]);
function refRuns(g){const runs=[];g.itens.forEach(x=>{if(x.i!==null)runs.push({inf:g.infos[x.i],items:[x]});else runs[runs.length-1].items.push(x)});return runs}
function refMulti(g){const sp=n=>n>1?` rowspan="${n}"`:'';
const body=refRuns(g).map(({inf,items})=>{const n=items.length,ms=refMethods(inf),rows=Math.max(n,ms.length,1),req=inf.notas.length?inf.notas.map(refNota).join('<br>'):'—';
return Array.from({length:rows},(_,r)=>{let h='';
if(n===1){if(r===0)h+=`<td${sp(rows)}>${refItem(items[0].o)}</td><td${sp(rows)}>${refArrow}</td><td${sp(rows)}>${refItem(items[0].r)}</td>`}else if(r<n)h+=`<td>${refItem(items[r].o)}</td><td>${refArrow}</td><td>${refItem(items[r].r)}</td>`;else h+='<td></td><td></td><td></td>';
if(r===0)h+=`<td${sp(rows)}>${req}</td>`;
if(!ms.length){if(r===0)h+=`<td${sp(rows)} colspan="3">—</td>`}else if(ms.length===1){if(r===0)h+=ms[0].map(c=>`<td${sp(rows)}>${c}</td>`).join('')}else if(r<ms.length)h+=ms[r].map(c=>`<td>${c}</td>`).join('');else h+='<td></td><td></td><td></td>';
return `<tr>${h}</tr>`}).join('')}).join('');
return tbl(ths(['Item original','→','Item reformado','Requisitos','Método','Alteração no refino','Materiais']),body)}
function refSingle(g){const inf=g.infos[0];return `${refReq(inf)}${tbl(ths(['Item original','→','Item reformado']),trs(g.itens.map(x=>[refItem(x.o),refArrow,refItem(x.r)])))}<p class="table-search-note" style="margin:14px 0 6px;font-size:14px;font-weight:700">Custo da reforma</p>${tbl(ths(['Método','Alteração no refino','Materiais']),trs(refMethods(inf)))}`}
const refGrupo=g=>fold(esc(g.titulo),g.infos.length===1?refSingle(g):refMulti(g),{count:`${g.itens.length} ${g.itens.length===1?'item':'itens'}`});
const refEquipe=e=>fold(`${esc(e.nome)} <small>(${esc(e.sufixo)})</small>`,`<p class="table-search-note">Armas reformadas pela ${esc(e.nome)} serão marcadas como <b>${esc(e.sufixo)}</b> no final dos nomes. São feitas pelo Pesquisador (/navi ${esc(e.navi)}).</p>${e.grupos.map(refGrupo).join('')}`,{open:true,cls:'fold-team'});
function refMinerais(){const cats=[['Inferior',null,'10.000z'],['Comum','Inferior','10.000z'],['Incomum','Comum','20.000z'],['Superior','Incomum','50.000z']],tipos=['Arma','Armadura','Acessório'];
return tbl(ths(['Categoria','Item','Materiais','Zeny']),cats.map(([c,prev,z])=>tipos.map((tp,i)=>`<tr>${i===0?`<td rowspan="3">${c}</td>`:''}<td><span class="item-label">${itemLink(`Semijoia ${c} de ${tp}`)}</span></td><td>${prev?cst('',[[3,`Semijoia ${prev} de ${tp}`]]):cst('',[[1,'Sombridecon']])}</td>${i===0?`<td rowspan="3">${z}</td>`:''}</tr>`).join('')).join(''))}
function reformView(){const eq=(db.reformaPagina?.equipes)||[];
return `<div class="page-head"><div><div class="eyebrow">MELHORIAS DE EQUIPAMENTO</div><h1 class="page-title">Reforma</h1><p class="page-subtitle">Página Reforma da bROWiki: equipes de reforma, armas Fides e minerais.</p></div><span class="count-pill">${eq.length} EQUIPES + FIDES</span></div>
<div class="panel-note">Reforma é um sistema que permite transformar seus equipamentos em versões mais poderosas. Para reformar um item, vá ao Laboratório Regenschirm e fale com a Promotora de Reformas, no Shopping (/navi itemmall 15/50) ou em Lighthalzen (/navi lighthalzen 99/156). O processo exige o equipamento com o nível de refino e os materiais corretos. <a class="table-link" href="${BW}Reforma" target="_blank" rel="noopener noreferrer">Fonte: bROWiki — Reforma ↗</a></div>
${secH('Reformas','Cada equipe marca as armas reformadas com um sufixo no nome. Clique no título de uma seção para recolher ou abrir.')}${eq.map(refEquipe).join('')}
${fold('Armas Fides — conversão de Adulter Fides para Vivatus Fides','<div id="reformNote"></div><div class="toolbar"><input id="tableSearch" type="search" placeholder="Buscar arma ou classe…" value="'+esc(globalTerm)+'"></div><div id="reformConversionMount"></div>',{open:true,cls:'fold-top'})}
${fold('Custo da reforma — armas Fides','<p class="table-search-note">Há três rituais possíveis; cada um tem seu custo e sua perda de refino. Valem para qualquer arma Adulter Fides (+9 ou mais).</p><div id="reformCostMount"></div>',{open:true,cls:'fold-top'})}
${fold('Minerais','<p class="table-search-note">São fabricados pelo Pesquisador de Minérios (/navi rgsr_in 131/187). Você também pode refinar os minerais em semijoias com o mesmo NPC.</p>'+refMinerais(),{open:true,cls:'fold-top'})}`}

/* ===== Guia de Episódio + Cópia rápida de /navi ===== */
let guideTab = 'principal';
let activeEpid = null;

function naviBtn(cmd) {
  if (!cmd) return '';
  return `<button type="button" class="navi-chip" data-copy-navi="${esc(cmd)}" title="Clique para copiar ${esc(cmd)}"><code>${esc(cmd)}</code></button>`;
}

const richText = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])).replace(/\n/g, '<br>').replace(/\{\{([^}]+)\}\}/g, (_, n) => itemLink(n));
function guideEps() { return [...(db.guia || [])].sort((a, b) => episodeRank(a.titulo) - episodeRank(b.titulo)); }
function pickEp() { const eps = guideEps(); return eps.find(e => e.id === activeEpid) || eps[eps.length - 1]; }
function epSwitcher() { return `<div class="toolbar" style="margin-bottom:14px"><label for="epSelect" style="font-size:14px">Episódio:</label><select id="epSelect">${guideEps().map(e => `<option value="${esc(e.id)}"${e.id === pickEp().id ? ' selected' : ''}>${esc(e.titulo)}</option>`).join('')}</select></div>`; }
function stepList(list) { return list.map((p, i) => `<li class="guide-step"><span class="step-num">${i + 1}.</span> <span class="step-text">${esc(p.texto)}</span>${naviBtn(p.navi)}</li>`).join(''); }
function itensEtapa(list) { return list?.length ? `<p class="gift-line"><b>Itens desta etapa:</b> ${list.map(richText).join(' · ')}</p>` : ''; }
function itensNecessariosHtml(ep) {
  const it = ep.itensNecessarios;
  if (!it) return '';
  const block = t => t ? fold(esc(t.titulo), tableFrame(t.colunas.map(esc), trs(t.linhas.map(r => r.map(richText))), 'align-top'), { count: `${t.linhas.length} itens` }) : '';
  const embarque = it.embarque ? fold(esc(it.embarque.titulo), `${tableFrame(it.embarque.colunas.map(esc), trs(it.embarque.linhas.map(r => r.map(richText))), 'align-top')}${it.observacaoEquip ? `<p class="gift-line"><b>Equipamentos e encantamentos:</b> ${richText(it.observacaoEquip)}</p>` : ''}${it.nota ? `<p class="gift-line">${richText(it.nota)}</p>` : ''}`, { open: true, count: `${it.embarque.linhas.length} itens` }) : '';
  return `<section class="itens-necessarios">
    <div class="section-heading"><div><h2>Itens necessários</h2><p>Lista completa antes do passo a passo: farm compartilhado, itens só das diárias e o que levar de Midgard.</p></div></div>
    ${block(it.farm)}${block(it.diarias)}${embarque}
  </section>`;
}

function guideView() {
  const ep = pickEp();
  if (!ep) return `<div class="panel-note">Nenhum guia de episódio carregado.</div>`;

  const avisosHtml = ep.avisos?.length
    ? `<div class="panel-note"><b>Pontos de atenção:</b><ul style="margin:6px 0 0 18px">${ep.avisos.map(a => `<li>${esc(a)}</li>`).join('')}</ul></div>`
    : '';

  const principalHtml = ep.principal.map((cap, idx) => {
    const body = `${itensEtapa(cap.itens)}${cap.nota ? `<p class="gift-line">⚠️ ${esc(cap.nota)}</p>` : ''}${cap.recompensa ? `<p class="gift-line">🎁 ${esc(cap.recompensa)}</p>` : ''}<ol class="guide-steps">${stepList(cap.passos)}</ol>`;
    return fold(esc(cap.capitulo), body, { open: idx === 0, count: `${cap.passos.length} ${cap.passos.length === 1 ? 'passo' : 'passos'}` });
  }).join('');

  const secundariasHtml = ep.secundarias.map(sec => {
    const meta = [
      sec.prerequisito && `<b>Pré:</b> ${esc(sec.prerequisito)}`,
      sec.recompensa && `🎁 ${esc(sec.recompensa)}`
    ].filter(Boolean).join(' · ');
    const body = `${meta ? `<p class="gift-line">${meta}</p>` : ''}${itensEtapa(sec.itens)}<ol class="guide-steps">${stepList(sec.passos)}</ol>`;
    return fold(`${esc(sec.codigo)} — ${esc(sec.titulo)}`, body, { count: `${sec.passos.length} ${sec.passos.length === 1 ? 'passo' : 'passos'}` });
  }).join('');

  return `
    <div class="page-head">
      <div>
        <div class="eyebrow">PASSO A PASSO · QUESTS</div>
        <h1 class="page-title">${esc(ep.titulo)}</h1>
        <p class="page-subtitle">${esc(ep.requisitos)} · ${esc(ep.recompensaTotal)}</p>
      </div>
    </div>
    ${epSwitcher()}
    ${avisosHtml}
    ${itensNecessariosHtml(ep)}
    <div class="section-heading"><div><h2>Passo a passo</h2><p>Capítulos da história e missões secundárias, com /navi copiável em cada etapa.</p></div></div>
    <div class="up-controls" style="margin-bottom:14px">
      <div class="subtabs" role="group" aria-label="Tipo de missão">
        <button class="subtab ${guideTab === 'principal' ? 'active' : ''}" data-guide-tab="principal" type="button">Quest Principal (${ep.principal.length} etapas)</button>
        <button class="subtab ${guideTab === 'secundarias' ? 'active' : ''}" data-guide-tab="secundarias" type="button">Missões Secundárias (${ep.secundarias.length})</button>
      </div>
    </div>
    <div id="guideBody">
      ${guideTab === 'principal' ? principalHtml : secundariasHtml}
    </div>
  `;
}

function diariasView() {
  const ep = pickEp();
  if (!ep?.diarias) return `<div class="panel-note">Nenhuma diária catalogada para este episódio.</div>`;
  const total = ep.diarias.grupos.reduce((a, g) => a + g.diarias.length, 0);
  const groups = ep.diarias.grupos.map(gr => {
    const body = trs(gr.diarias.map(d => [d.linkBrowiki ? `<a class="table-link" href="${d.linkBrowiki}" target="_blank" rel="noopener noreferrer" title="Abrir na bROWiki">${esc(d.nome)} ↗</a>` : esc(d.nome), richText(d.tarefa), richText(d.itens), richText(d.recompensa), d.obs ? esc(d.obs) : '']));
    return `<section class="table-section"><div class="table-section-head"><h2>${esc(gr.nome)}</h2><span>${gr.diarias.length} diária${gr.diarias.length > 1 ? 's' : ''}</span></div>${tableFrame(['Diária', 'Tarefa', 'Itens', 'Recompensa', 'Observação'], body, 'align-top')}</section>`;
  }).join('');
  return `<div class="page-head"><div><div class="eyebrow">DIÁRIAS DE EPISÓDIO</div><h1 class="page-title">${esc(ep.diarias.titulo)}</h1><p class="page-subtitle">Tarefas repetíveis do episódio, com os itens de cada uma.</p></div><span class="count-pill">${total} DIÁRIAS</span></div>${epSwitcher()}<div class="panel-note">${richText(ep.diarias.aviso)}</div>${groups}<div class="section-heading"><div><h2>Onde obter por episódio</h2><p>Fontes de materiais e moedas do episódio selecionado; marque os bônus de reputação para incluí-los nos totais.</p></div></div><div id="obtencaoMount"></div>`;
}

document.addEventListener('click', e => {
  const tabBtn = e.target.closest('[data-guide-tab]');
  if (tabBtn) {
    guideTab = tabBtn.dataset.guideTab;
    render();
    return;
  }
  const copyBtn = e.target.closest('[data-copy-navi]');
  if (copyBtn) {
    const text = copyBtn.dataset.copyNavi;
    navigator.clipboard?.writeText(text).then(() => {
      const old = copyBtn.title;
      copyBtn.classList.add('copied');
      copyBtn.title = 'Copiado!';
      setTimeout(() => { copyBtn.classList.remove('copied'); copyBtn.title = old; }, 1400);
    });
  }
});

loadData().then(()=>{setView('inicio')}).catch(err=>{$('#content').innerHTML=`<div class="error-box"><b>Não consegui carregar a biblioteca.</b><br>${esc(err.message)}<br>Abra o site por um servidor local ou publique a pasta inteira no GitHub Pages; os arquivos de dados precisam ficar ao lado do site em <code>data/</code>.</div>`});
